// 段、作者和真实事实必须一同选择；未启用时不得出现新空尾或新命令来源。
#include "political_succession_profile.hpp"
#include "resident/domains/politics/takeover/politics_takeover_payload_guard.hpp"
#include <map>
namespace hanmo::resident {
bool is_political_succession_fact_kind(const StableId& k){return k=="political_successor_nominated"||k=="political_succession_accepted"||k=="political_succession_declined"||k=="political_succession_withdrawn"||k=="political_succession_acceded";}
Outcome<Integer> political_succession_selected_version(const std::vector<std::pair<StableId,StableId>>& modules){Integer count=0;for(const auto& m:modules)if(m.first==political_succession_domain){if(m.second!="1"||++count!=1)return {false,0,common_failure("PoliticalSuccessionModuleMismatch",m.first).error};}if(!count)return {true,0,{}};std::map<StableId,Integer> dependencies;for(const auto& m:modules)if(m.first=="politics"||m.first=="family_life"||m.first=="task_message_notices"||m.first=="task_message_handoffs"){if((m.first=="task_message_handoffs"?(m.second!="1"&&m.second!="2"):m.second!="1")||++dependencies[m.first]!=1)return {false,0,common_failure("PoliticalSuccessionDependenciesRequired",m.first).error};}for(const auto* name:{"politics","family_life","task_message_notices","task_message_handoffs"})if(dependencies[name]!=1)return {false,0,common_failure("PoliticalSuccessionDependenciesRequired",name).error};return {true,1,{}};}
// 只读取显式作者政策，不能在新局注入意愿、死亡、实交或正式Office变更。
Outcome<std::optional<PoliticalSuccessionCatalog>> decode_political_succession_profile(const BoundaryValue& scenario,const std::vector<StableId>& capabilities){const auto* dynamic=scenario.find("dynamic_world");const auto* group=dynamic?dynamic->find(political_succession_domain):nullptr;if(!group)return {true,std::nullopt,{}};if(std::find(capabilities.begin(),capabilities.end(),"political_successions_v1")==capabilities.end())return {false,{},common_failure("PoliticalSuccessionCapabilityRequired").error};try{using namespace boundary;if(get_string(*dynamic,"profile","dynamic_world")!="local_society_v1"||!dynamic->find("politics")||!dynamic->find("organization")||!scenario.find("family_life")||!scenario.find("task_message_notices"))return {false,{},common_failure("PoliticalSuccessionDependenciesRequired").error};auto catalog=decode_political_succession_catalog(*group);if(!catalog.ok)return {false,{},catalog.error};if(catalog.value.policies.empty()||catalog.value.policies.size()>4096)return {false,{},common_failure("InvalidPoliticalSuccessionCatalog").error};return {true,std::move(catalog.value),{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Status validate_political_succession_layout(const CommonStore& common,const std::vector<std::pair<StableId,StableId>>& modules,const PoliticalSuccessionState* state){auto selected=political_succession_selected_version(modules);if(!selected.ok)return {false,{},selected.error};if(bool(state)!=(selected.value==1)||(state&&(state->version!=1||state->nominations.version!=1||state->accessions.version!=1)))return common_failure("PoliticalSuccessionProfileMismatch");if(!state){for(const auto& row:common.state().facts.rows())if(is_political_succession_fact_kind(row.second.kind)||row.second.domain==political_succession_domain)return common_failure("PoliticalSuccessionProfileRequired",row.first);for(const auto& h:common.state().history)if(is_political_succession_command(h.kind))return common_failure("PoliticalSuccessionProfileRequired",h.result_id);for(const auto& row:common.state().results.rows())if(row.second&&is_political_succession_command(row.second->kind))return common_failure("PoliticalSuccessionProfileRequired",row.first);}return common_success();}
// JSON无附加载荷只允许五类真实表项各唯一匹配，domain不是通配事实豁免。
Status validate_political_succession_fact_header(const CommonStore& common,const PoliticalSuccessionState& s,const FactRecord& h){auto n=political_succession_fact_sequence(common,h.id);const auto* a=s.nominations.nominations.find(h.id);const auto* b=s.nominations.answers.find(h.id);const auto* c=s.nominations.withdrawals.find(h.id);const auto* d=s.accessions.accessions.find(h.id);if(s.version!=1||s.nominations.version!=1||s.accessions.version!=1||!n||h.domain!=political_succession_domain||Integer(bool(a))+Integer(bool(b))+Integer(bool(c))+Integer(bool(d))!=1)return common_failure("PoliticalSuccessionFactMismatch",h.id);const auto& id=a?a->id:b?b->id:c?c->id:d->id;const StableId kind=a?"political_successor_nominated":b?(b->accepted?"political_succession_accepted":"political_succession_declined"):c?"political_succession_withdrawn":"political_succession_acceded";return id==h.id&&h.kind==kind?common_success():common_failure("PoliticalSuccessionFactMismatch",h.id);}
}
